apiVersion: apps/v1
kind: Deployment
metadata: {name: harbor-cost-lab}
spec:
  replicas: 3
  selector: {matchLabels: {app: harbor-cost-lab}}
  template:
    metadata: {labels: {app: harbor-cost-lab}}
    spec:
      containers:
        - name: app
          image: harbor-service:lab
          imagePullPolicy: Never
          resources:
            requests: {cpu: 150m, memory: 96Mi}
            limits: {memory: 192Mi}

